import React, { createContext, useContext, useState, useEffect } from 'react';

const LanguageContext = createContext();

const translations = {
  en: {
    // Navigation
    'home': 'Home',
    'products': 'Products',
    'cart': 'Cart',
    'orders': 'Orders',
    'track': 'Track Order',
    'login': 'Login',
    'logout': 'Logout',
    'register': 'Register',
    'my_account': 'My Account',
    'admin': 'Admin',
    
    // Home page
    'welcome': 'Welcome to Our Store',
    'best_sellers': 'Best Sellers',
    'new_products': 'New Products',
    'deal_of_day': 'Deal of the Day',
    'see_more': 'See More Products',
    'add_to_cart': 'Add to Cart',
    'view_details': 'View Details',
    
    // Products
    'all_products': 'All Products',
    'search': 'Search products...',
    'sort_by': 'Sort By',
    'price_low_high': 'Price: Low to High',
    'price_high_low': 'Price: High to Low',
    'newest': 'Newest',
    'filter': 'Filter',
    'category': 'Category',
    
    // Cart
    'your_cart': 'Your Cart',
    'empty_cart': 'Your cart is empty',
    'continue_shopping': 'Continue Shopping',
    'checkout': 'Checkout',
    'total': 'Total',
    'quantity': 'Quantity',
    'remove': 'Remove',
    
    // Checkout
    'shipping_address': 'Shipping Address',
    'payment_method': 'Payment Method',
    'order_summary': 'Order Summary',
    'place_order': 'Place Order',
    'proceed': 'Proceed',
    
    // Order Tracking
    'order_id': 'Order ID',
    'status': 'Status',
    'tracking': 'Tracking',
    'pending': 'Pending',
    'processing': 'Processing',
    'shipped': 'Shipped',
    'delivered': 'Delivered',
    
    // Auth
    'email': 'Email',
    'password': 'Password',
    'confirm_password': 'Confirm Password',
    'sign_in': 'Sign In',
    'sign_up': 'Sign Up',
    'dont_have_account': "Don't have an account?",
    'already_have_account': 'Already have an account?',
    
    // Messages
    'loading': 'Loading...',
    'error': 'Error',
    'success': 'Success',
    'try_again': 'Try Again',
  },
  hi: {
    // Navigation
    'home': 'होम',
    'products': 'उत्पाद',
    'cart': 'कार्ट',
    'orders': 'आदेश',
    'track': 'ऑर्डर ट्रैक करें',
    'login': 'लॉगिन',
    'logout': 'लॉगआउट',
    'register': 'रजिस्टर',
    'my_account': 'मेरा खाता',
    'admin': 'एडमिन',
    
    // Home page
    'welcome': 'हमारे स्टोर में आपका स्वागत है',
    'best_sellers': 'सबसे ज्यादा बिकने वाले',
    'new_products': 'नए उत्पाद',
    'deal_of_day': 'दिन का डील',
    'see_more': 'और देखें',
    'add_to_cart': 'कार्ट में जोड़ें',
    'view_details': 'विवरण देखें',
    
    // Products
    'all_products': 'सभी उत्पाद',
    'search': 'उत्पाद खोजें...',
    'sort_by': 'द्वारा क्रमबद्ध करें',
    'price_low_high': 'कीमत: कम से अधिक',
    'price_high_low': 'कीमत: अधिक से कम',
    'newest': 'नवीनतम',
    'filter': 'फ़िल्टर',
    'category': 'श्रेणी',
    
    // Cart
    'your_cart': 'आपका कार्ट',
    'empty_cart': 'आपका कार्ट खाली है',
    'continue_shopping': 'खरीदारी जारी रखें',
    'checkout': 'चेकआउट',
    'total': 'कुल',
    'quantity': 'मात्रा',
    'remove': 'हटाएं',
    
    // Checkout
    'shipping_address': 'शिपिंग पता',
    'payment_method': 'भुगतान विधि',
    'order_summary': 'ऑर्डर सारांश',
    'place_order': 'ऑर्डर रखें',
    'proceed': 'आगे बढ़ें',
    
    // Order Tracking
    'order_id': 'ऑर्डर ID',
    'status': 'स्थिति',
    'tracking': 'ट्रैकिंग',
    'pending': 'लंबित',
    'processing': 'प्रसंस्करण',
    'shipped': 'भेजा गया',
    'delivered': 'वितरित',
    
    // Auth
    'email': 'ईमेल',
    'password': 'पासवर्ड',
    'confirm_password': 'पासवर्ड की पुष्टि करें',
    'sign_in': 'साइन इन करें',
    'sign_up': 'साइन अप करें',
    'dont_have_account': 'खाता नहीं है?',
    'already_have_account': 'पहले से खाता है?',
    
    // Messages
    'loading': 'लोड हो रहा है...',
    'error': 'त्रुटि',
    'success': 'सफल',
    'try_again': 'फिर से प्रयास करें',
  }
};

export const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState(() => {
    return localStorage.getItem('language') || 'en';
  });

  useEffect(() => {
    localStorage.setItem('language', language);
  }, [language]);

  const t = (key) => {
    return translations[language]?.[key] || translations['en']?.[key] || key;
  };

  const toggleLanguage = () => {
    setLanguage((prev) => (prev === 'en' ? 'hi' : 'en'));
  };

  return (
    <LanguageContext.Provider value={{ language, t, toggleLanguage }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within LanguageProvider');
  }
  return context;
};
